/**
 * Where the Agent Host comes from: the packaged app's resources, or a Node executable and a
 * bundle (development).
 */
export interface AgentHostOptions {
  /** Electron's `process.resourcesPath` of a packaged app (`agent-host/` below it). */
  resourcesPath?: string;
  /** Development: the Node executable. */
  node?: string;
  /** Development: `agent-host.mjs`. */
  bundle?: string;
  /** Development: Pi's resources next to the bundle (`pi-assets/`). */
  piPackageDir?: string;
}

/** What `agentHostProbe` runs (S6, T12): see `piarc_core::host_probe`. */
export interface AgentHostProbeOptions {
  /** The app's resources directory (`process.resourcesPath`). */
  resourcesDir: string;
  /** Workspace root (absolute, existing). */
  workspace: string;
  /** Data directory for the Agent Host (absolute, existing; `pi/models.json` inside). */
  dataDir: string;
  /** Provider id of the session's model. */
  provider: string;
  /** Model id. */
  model: string;
  /** The prompt. */
  prompt: string;
  /** Upper bound of the conversation in milliseconds. Default 60,000. */
  timeoutMs?: number;
}

/** One batch as JavaScript receives it. */
export interface CoreEventBatch {
  /** Route key: the topic the main process forwards the batch under. */
  route: string;
  /** Per-route batch number, starting at 1 and consecutive. */
  seq: number;
  /** UTF-8 JSON array of the batch's events. Opaque to the main process. */
  payload: Uint8Array;
}

/** Counters of the event path. */
export interface CoreEventStats {
  /** Events accepted into the queue. */
  queued: number;
  /** Calls of `onEvents`. */
  deliveries: number;
  /** Batches passed to `onEvents`. */
  batches: number;
  /** Events passed to `onEvents`. */
  delivered: number;
  /** Events dropped because the listener's environment was gone. */
  lost: number;
}

/** Options of `CoreRuntime.create`. */
export interface CoreOptions {
  /** Coalescing interval in milliseconds (1 to 1000). Default 16. */
  coalesceIntervalMs?: number;
  /**
   * Absolute data directory (architecture section 9.1). With `cacheDir`, Core opens its
   * database, settings, project trust and log files there; without both, none of them.
   */
  dataDir?: string;
  /** Absolute cache directory (discardable). */
  cacheDir?: string;
  /** How workspaces start their Agent Host; without it workspaces cannot open. */
  agentHost?: AgentHostOptions;
  /**
   * Idle time in milliseconds after which a workspace's Agent Host is stopped (default 30
   * minutes).
   */
  idleTimeoutMs?: number;
}

/** Lifecycle state of a runtime. */
export type CoreState = 'running' | 'shuttingDown' | 'stopped';

/** Options of `createSession`. */
export interface CreateSessionOptions {
  /** Absolute working directory inside the workspace; the workspace itself when absent. */
  cwd?: string;
  /** The model to start with; the Agent Host's default when absent. */
  model?: SessionModel;
  /** Optional explicit M1 permission mode. */
  permissionMode?: string;
}

/** Settings of a demo event source. */
export interface DemoSourceOptions {
  /** Route key of every event. */
  route: string;
  /** Target rate in events per second, fractions allowed (above 0, at most 1,000,000). */
  eventsPerSecond: number;
  /** Length of each event's `pad` string, to control the payload size. Default 0. */
  padBytes?: number;
  /** Stop after this many events. Default: run until stopped. */
  maxEvents?: number;
}

/** The result of a stopped demo source. */
export interface DemoSourceReport {
  /** The source id. */
  id: number;
  /** Events queued; each one is delivered unless the listener's environment is gone. */
  emitted: number;
}

/** A model by provider and id. */
export interface SessionModel {
  /** Provider id, for example `anthropic`. */
  provider: string;
  /** Model id within the provider. */
  id: string;
}

/** Options of `createTerminal`. */
export interface TerminalCreateOptions {
  /** Columns (1 to 1000). */
  cols: number;
  /** Rows (1 to 1000). */
  rows: number;
  /** Cell width in device-independent pixels, for pixel size reports. Default 8. */
  cellWidth?: number;
  /** Cell height. Default 16. */
  cellHeight?: number;
  /** Program to run instead of the user's login shell. */
  program?: string;
  /** Arguments of `program`. */
  args?: string[];
  /** Absolute working directory; the home directory when unset. */
  cwd?: string;
  /** Extra environment variables. */
  env?: Record<string, string>;
}

/** A key event as the renderer saw it. */
export interface TerminalKeyEvent {
  /** `press`, `repeat` or `release`. */
  action: string;
  /** `KeyboardEvent.code`. */
  code: string;
  /** The character the key produced; empty for named keys (Enter, arrows, F-keys). */
  text: string;
  /** Bits: 1 Shift, 2 Ctrl, 4 Alt/Option, 8 Meta/Command. */
  mods: number;
  /** The event belongs to an input-method composition. */
  composing: boolean;
}

/** Counters of one terminal (T10 measurements). */
export interface TerminalStats {
  /** Bytes read from the PTY. */
  bytesRead: number;
  /** Reads from the PTY. */
  reads: number;
  /** Time spent parsing output (`vt_write`), in microseconds. */
  vtWriteMicros: number;
  /** Frames produced, empty ones included. */
  frames: number;
  /** Empty frames. */
  emptyFrames: number;
  /** Bytes of all frames. */
  frameBytes: number;
  /** Time spent producing frames, in microseconds. */
  frameMicros: number;
  /** Rows sent with cells. */
  rowsWithCells: number;
  /** Rows sent as references. */
  rowsReused: number;
}
